<style>
.execution-monitor{min-width:0}.execution-toolbar{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.execution-toolbar h2{font-size:25px;margin-bottom:10px}.execution-toolbar p{max-width:580px;margin:0}.execution-toolbar .btn{flex-shrink:0}.execution-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.execution-metric{padding:20px;border:1px solid var(--line);border-radius:16px;background:#fff}.execution-metric strong{display:block;font-size:30px;letter-spacing:-.04em;line-height:1.3;margin:6px 0}.execution-metric span,.execution-metric small{font-size:12px;color:var(--muted)}.execution-metric.attention{border-color:#e4c2ad;background:#fffaf6}.execution-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.execution-card{display:flex;flex-direction:column;gap:16px;min-width:0;padding:22px;background:#fff;border:1px solid var(--line);border-radius:17px}.execution-card h3{font-size:16px;margin:5px 0;overflow-wrap:anywhere}.execution-card .quiet{margin:0}.execution-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.execution-reference{font-size:11px;color:var(--muted);letter-spacing:.06em;text-transform:uppercase}.execution-badge{display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:8px;font-size:12px;font-weight:750;line-height:1.4;max-width:100%}.execution-badge:before{content:"";width:7px;height:7px;flex-shrink:0;border-radius:50%;background:currentColor}.execution-badge[data-execution-state="UNOBSERVED"],.execution-badge[data-execution-state="NOT_STAGED"]{background:#f0efed;color:#595653}.execution-badge[data-execution-state="NOT_STARTED"]{background:#fff1de;color:#875008}.execution-badge[data-execution-state="STARTED"]{background:#eaf1f9;color:#315b80}.execution-badge[data-execution-state="RESULT"]{background:#eeeafa;color:#65448b}.execution-badge[data-execution-state="ACKED"]{background:#e7f4eb;color:#236542}.execution-badge[data-execution-state="UNKNOWN"]{background:#faebe6;color:#963e2a}.execution-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:0}.execution-facts div{min-width:0}.execution-facts dt{font-size:11px;color:var(--muted);margin-bottom:4px}.execution-facts dd{margin:0;font-size:13px;font-weight:650;overflow-wrap:anywhere}.execution-card-foot{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--line);padding-top:15px;margin-top:auto}.execution-card-foot a{font-size:13px;font-weight:750;color:#8d4e08}.execution-card-foot span{font-size:11px;color:var(--muted)}.execution-subtitle{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap}.execution-subtitle h3{margin:0}.execution-subtitle p{margin:0}.execution-note{font-size:13px;color:var(--muted);border-left:3px solid #e7b477;padding:3px 0 3px 15px;margin:0}.execution-empty{padding:40px 24px;text-align:center;border:1px dashed #dbcdbd;border-radius:17px;background:#fffdf9}.execution-empty h3{font-size:19px}.execution-empty p{max-width:520px;margin:0 auto;color:var(--muted);font-size:14px}.execution-detail .execution-card-top{margin-bottom:20px}.execution-detail h2{overflow-wrap:anywhere}.execution-detail .execution-facts{grid-template-columns:repeat(3,minmax(0,1fr));padding-top:20px;border-top:1px solid var(--line)}.execution-attention{background:#fff3ed;border:1px solid #ebc7b6;border-radius:12px;padding:17px 19px;margin-top:20px}.execution-attention strong{color:#7d3c24;display:block;margin-bottom:7px}.execution-attention p{font-size:13px;margin:0;color:#744c3a}.execution-timeline{list-style:none;padding:0;margin:24px 0 0}.execution-timeline li{position:relative;margin:0 0 0 7px;padding:0 0 24px 24px;border-left:2px solid #eee5d9}.execution-timeline li:last-child{padding-bottom:0;border-color:transparent}.execution-timeline li:before{content:"";position:absolute;left:-7px;top:8px;width:12px;height:12px;border:3px solid #fff;border-radius:50%;background:#e5bb85;box-shadow:0 0 0 1px #e4d6c5}.execution-timeline li:first-child:before{background:var(--orange)}.execution-timeline-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.execution-timeline time{font-size:12px;color:var(--muted)}.execution-timeline p{font-size:13px;margin:10px 0 4px}.execution-timeline small{font-size:12px;color:var(--muted)}.execution-back{font-size:13px;font-weight:700;color:#8d4e08}.execution-full-reference{font:12px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.execution-caption{font-size:12px;color:var(--muted);margin:0}.execution-monitor time{white-space:normal}
