@media(max-width:600px){.execution-card,.execution-detail{padding:18px}.execution-detail .execution-card-top{flex-direction:column}.execution-detail .execution-facts{grid-template-columns:repeat(2,minmax(0,1fr))}.execution-facts{gap:14px 12px}.execution-metric{padding:15px}.execution-metric strong{font-size:27px}.execution-card-foot{align-items:flex-start;flex-direction:column;gap:6px}.execution-timeline li{padding-left:19px}.execution-toolbar .btn{width:100%}.execution-subtitle{align-items:flex-start;flex-direction:column}.execution-detail h2{font-size:22px}}
